class Scoreboard {
  private scores = new Map<number, number>();

  addScore(playerId: number, score: number): void {
    this.scores.set(playerId, (this.scores.get(playerId) ?? 0) + score);
  }

  top(k: number): number {
    const heap: number[] = []; // min-heap
    const push = (v: number) => {
      heap.push(v);
      let i = heap.length - 1;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (heap[p] <= heap[i]) break;
        [heap[p], heap[i]] = [heap[i], heap[p]];
        i = p;
      }
    };
    const pop = () => {
      const last = heap.pop()!;
      if (heap.length === 0) return;
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < heap.length && heap[l] < heap[m]) m = l;
        if (r < heap.length && heap[r] < heap[m]) m = r;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]];
        i = m;
      }
    };
    for (const v of this.scores.values()) {
      push(v);
      if (heap.length > k) pop();
    }
    return heap.reduce((a, b) => a + b, 0);
  }

  reset(playerId: number): void {
    this.scores.delete(playerId);
  }
}

